content:
@layer tokens {
  :root {
    --shelf-base-accent-5: hsl(18 55% 42%);
    --shelf-bgColor-overlay: hsl(16 12% 10% / 0.5);
  }
}

@layer base {
  body { margin: 0; background-color: var(--shelf-bgColor-default); }
}

@layer components {
  .chip {
    color: var(--shelf-fgColor-default);
    background-color: var(--shelf-bgColor-accent);
    border-color: var(--shelf-borderColor-subtle);
  }
}

@layer components {
  .chip {
    color: color-mix(in srgb, var(--shelf-fgColor-accent), var(--shelf-fgColor-default));
  }
}

@layer components {
  .chip-bar {
    display: flex;
    flex-wrap: wrap;
    gap: var(--shelf-space-sm);
  }

  .chip {
    display: inline-flex;
    align-items: center;
    padding-block: var(--shelf-space-sm);
    padding-inline: var(--shelf-space-md);
    border-style: solid;
    border-width: var(--shelf-border-width);
    border-color: var(--shelf-borderColor-subtle);
    border-radius: var(--shelf-radius-full);
    background-color: transparent;
    color: var(--shelf-fgColor-default);
    font-family: var(--shelf-font-family-base);
    font-size: var(--shelf-font-size-sm);
    font-weight: var(--shelf-font-weight-medium);
    cursor: pointer;
  }

  .chip[aria-pressed='true'] {
    border-color: var(--shelf-bgColor-accent);
    background-color: var(--shelf-bgColor-accent);
    color: var(--shelf-fgColor-on-accent);
  }
}
